WITH lines AS (SELECT id, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) e AS element) SELECT CASE WHEN element >= 82 THEN 'HIGH' ELSE 'LOW' END AS element_tier, COUNT(*) AS cnt, PERCENTILE_APPROX(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles, APPROX_PERCENTILE(element, 0.95) AS element_p95 FROM lines GROUP BY CASE WHEN element >= 82 THEN 'HIGH' ELSE 'LOW' END ORDER BY cnt DESC;
